class SaveConflict(RuntimeError):
    pass

def load_state(client, profile):
    rows = client.table(TABLE).select("payload,revision").eq("profile_id", profile).limit(1).execute().data
    if not rows:
        return {"config": {"count": 12, "voice": False, "auto": True}, "records": [], "session": None}, None
    return rows[0]["payload"], int(rows[0]["revision"])

def validate_state(state):
    if not isinstance(state, dict) or not isinstance(state.get("records"), list):
        raise ValueError("学習記録の形式が正しくありません。")
    config = state.get("config", {})
    if config.get("count") != 12:
        raise ValueError("問題数の設定が正しくありません。")
    if type(config.get("age", 5)) is not int or not 3 <= config.get("age", 5) <= 12:
        raise ValueError("年齢の設定が正しくありません。")
    counters = state.get("challengeCounts", {})
    if not isinstance(counters, dict):
        raise ValueError("チャレンジ回数の形式が正しくありません。")
    for per_level in counters.values():
        if not isinstance(per_level, dict):
            raise ValueError("チャレンジ回数の形式が正しくありません。")
        for counts in per_level.values():
            if (not isinstance(counts, dict) or
                any(type(counts.get(k)) is not int or counts[k] < 0 for k in ("started", "completed")) or
                counts["completed"] > counts["started"]):
                raise ValueError("チャレンジ回数の値が正しくありません。")
    if len(state["records"]) > 1500 or len(json.dumps(state, ensure_ascii=False).encode()) > 2_000_000:
        raise ValueError("保存データの上限を超えています。")
    if state.get("session") is not None and not isinstance(state["session"], dict):
        raise ValueError("途中データの形式が正しくありません。")
    return state

def save_state(client, profile, state, revision):
    validate_state(state)
    next_revision = 1 if revision is None else revision + 1
    row = {"profile_id": profile, "payload": state, "revision": next_revision,
           "updated_at": datetime.now(timezone.utc).isoformat()}
    if revision is None:
        try:
            result = client.table(TABLE).insert(row).execute()
        except Exception as exc:
            if getattr(exc, "code", None) == "23505":
                raise SaveConflict("別の端末で更新されました。画面を再読み込みしてください。") from exc
            raise
    else:
        result = client.table(TABLE).update(row).eq("profile_id", profile).eq("revision", revision).execute()
    if not result.data:
        raise SaveConflict("別の端末で更新されました。画面を再読み込みしてください。")
    return next_revision

@st.cache_resource(max_entries=2)
def component(frontend):
    folder = Path(tempfile.gettempdir()) / ("chocomana_component_" + hashlib.sha256(frontend.encode()).hexdigest()[:16])
    folder.mkdir(parents=True, exist_ok=True)
    target = folder / "index.html"
    if not target.exists():
        tmp = folder / "index.tmp"
        tmp.write_text(frontend, encoding="utf-8")
        tmp.replace(target)
    return components.declare_component("chocomana_kotoba_" + hashlib.sha256(frontend.encode()).hexdigest()[:16], path=str(folder))

@st.cache_resource
def db_client(url, key):
    # The service key is used only by Python. It is never passed to the browser.
    return create_client(url, key)

def main():
    st.set_page_config(page_title="ちょこまな（国語） - ことば", page_icon="📖", layout="wide")
    st.markdown("<style>.stApp{background:#f7f5ef}.block-container{padding:0.5rem!important;max-width:1180px!important}header[data-testid=stHeader]{display:none}</style>", unsafe_allow_html=True)
    required = ("SUPABASE_URL", "SUPABASE_SERVICE_ROLE_KEY")
    try:
        missing = [key for key in required if not str(st.secrets.get(key, "")).strip()]
    except Exception:
        missing = list(required)
    if missing:
        st.title("ちょこまな（国語） - ことば")
        st.info("StreamlitのSecretsに接続設定を追加してください：" + "、".join(missing))
        st.stop()
    profile = str(st.secrets.get("CHOCOMANA_PROFILE_ID", "family_default"))
    client = db_client(st.secrets["SUPABASE_URL"], st.secrets["SUPABASE_SERVICE_ROLE_KEY"])
    if "cloud_state" not in st.session_state:
        try:
            state, revision = load_state(client, profile)
        except Exception:
            logging.exception("chocomana initial read failed")
            st.error("学習記録を読み込めません。Supabaseの接続設定・chocomana_stateテーブルを確認してください。")
            if st.button("再読み込み"):
                st.rerun()
            st.stop()
        st.session_state.cloud_state = state
        st.session_state.revision = revision
        st.session_state.processed_seq = 0
        st.session_state.ack = None
    event = component(FRONTEND)(initial=st.session_state.cloud_state, ack=st.session_state.ack, key="chocomana_board", default=None)
    if event and isinstance(event, dict) and isinstance(event.get("seq"), int) and event["seq"] > st.session_state.processed_seq:
        seq = event["seq"]
        try:
            state = validate_state(event["state"])
            revision = save_state(client, profile, state, st.session_state.revision)
            st.session_state.revision = revision
            st.session_state.cloud_state = state
            ack = {"seq": seq, "ok": True}
        except SaveConflict as exc:
            ack = {"seq": seq, "ok": False, "message": str(exc)}
        except Exception:
            logging.exception("chocomana save failed")
            ack = {"seq": seq, "ok": False, "message": "未保存：通信を確認して、保存を再試行してください。"}
        st.session_state.processed_seq = seq
        st.session_state.ack = ack
        st.rerun()

if __name__ == "__main__":
    main()
